def pbBeginTurn(_choice)
  # Cancel some lingering effects which only apply until the user next moves
  @effects[PBEffects::DestinyBondPrevious] = @effects[PBEffects::DestinyBond]
  @effects[PBEffects::DestinyBond]         = false
  @effects[PBEffects::Grudge]              = false
  @effects[PBEffects::MoveNext]            = false
  @effects[PBEffects::Quash]               = 0
  # Encore's effect ends if the encored move is no longer available
  if @effects[PBEffects::Encore] > 0 && pbEncoredMoveIndex < 0
    @effects[PBEffects::Encore]     = 0
    @effects[PBEffects::EncoreMove] = nil
  end
end

# Called when the usage of various multi-turn moves is disrupted due to
# failing pbTryUseMove, being ineffective against all targets, or because
# Pursuit was used specially to intercept a switching foe.
# Cancels the use of multi-turn moves and counters thereof. Note that Hyper
# Beam's effect is NOT cancelled.
def pbCancelMoves(full_cancel = false)
  # Outragers get confused anyway if they are disrupted during their final
  # turn of using the move
  if @effects[PBEffects::Outrage] == 1 && pbCanConfuseSelf?(false) && !full_cancel
    pbConfuse(_INTL("{1} became confused due to fatigue!", pbThis))
  end
  # Cancel usage of most multi-turn moves
  @effects[PBEffects::TwoTurnAttack] = nil
  @effects[PBEffects::Rollout]       = 0
  @effects[PBEffects::Outrage]       = 0
  @effects[PBEffects::Uproar]        = 0
  @effects[PBEffects::Bide]          = 0
  @currentMove = nil if @effects[PBEffects::HyperBeam] == 0
  # Reset counters for moves which increase them when used in succession
  @effects[PBEffects::FuryCutter] = 0
end

def pbEndTurn(_choice)
  @lastRoundMoved = @battle.turnCount   # Done something this round
  if !@effects[PBEffects::ChoiceBand] &&
     (hasActiveItem?([:CHOICEBAND, :CHOICESPECS, :CHOICESCARF]) ||
     hasActiveAbility?(:GORILLATACTICS))
    if @lastMoveUsed && pbHasMove?(@lastMoveUsed)
      @effects[PBEffects::ChoiceBand] = @lastMoveUsed
    elsif @lastRegularMoveUsed && pbHasMove?(@lastRegularMoveUsed)
      @effects[PBEffects::ChoiceBand] = @lastRegularMoveUsed
    end
  end
  @effects[PBEffects::BeakBlast]   = false
  @effects[PBEffects::Charge]      = 0 if @effects[PBEffects::Charge] == 1
  @effects[PBEffects::GemConsumed] = nil
  @effects[PBEffects::ShellTrap]   = false
  @battle.allBattlers.each { |b| b.pbContinualAbilityChecks }   # Trace, end primordial weathers
end

class Battle::Move::TrapTargetInBattleLowerTargetDefSpDef1EachTurn < Battle::Move
  def pbFailsAgainstTarget?(user, target, show_message)
    return false if damagingMove?
    if target.effects[PBEffects::Octolock] >= 0
      @battle.pbDisplay(_INTL("But it failed!")) if show_message
      return true
    end
    if Settings::MORE_TYPE_EFFECTS && target.pbHasType?(:GHOST)
      @battle.pbDisplay(_INTL("It doesn't affect {1}...", target.pbThis(true))) if show_message
      return true
    end
    return false
  end

  def pbEffectAgainstTarget(user, target)
    target.effects[PBEffects::Octolock] = user.index
    @battle.pbDisplay(_INTL("{1} can no longer escape because of {2}!", target.pbThis, @name))
  end
end

def abilityActive?(ignore_fainted = false, check_ability = nil)
  return false if fainted? && !ignore_fainted
  return false if @effects[PBEffects::GastroAcid]
  return false if check_ability != :NEUTRALIZINGGAS && self.ability != :NEUTRALIZINGGAS &&
                  @battle.pbCheckGlobalAbility(:NEUTRALIZINGGAS)
  return true
end

def hasActiveAbility?(check_ability, ignore_fainted = false)
  return false if !abilityActive?(ignore_fainted, check_ability)
  return check_ability.include?(@ability_id) if check_ability.is_a?(Array)
  return self.ability == check_ability
end

def hasMoldBreaker?
  return hasActiveAbility?([:MOLDBREAKER, :TERAVOLT, :TURBOBLAZE])
end

def ability=(value)
  new_ability = GameData::Ability.try_get(value)
  @ability_id = (new_ability) ? new_ability.id : nil
end

def itemActive?(ignoreFainted = false)
  return false if fainted? && !ignoreFainted
  return false if @effects[PBEffects::Embargo] > 0
  return false if @battle.field.effects[PBEffects::MagicRoom] > 0
  return false if @battle.corrosiveGas[@index % 2][@pokemonIndex]
  return false if hasActiveAbility?(:KLUTZ, ignoreFainted)
  return true
end

def hasActiveItem?(check_item, ignore_fainted = false)
  return false if !itemActive?(ignore_fainted)
  return check_item.include?(@item_id) if check_item.is_a?(Array)
  return self.item == check_item
end

def pbItemOnStatDropped(move_user = nil)
  return false if !@statsDropped
  return false if !itemActive?
  return Battle::ItemEffects.triggerOnStatLoss(self.item, self, move_user, @battle)
end

class HandlerHashSymbol
  def initialize
    @hash    = {}
    @add_ifs = {}
  end

  def [](sym)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    return @hash[sym] if sym && @hash[sym]
    @add_ifs.each_value do |add_if|
      return add_if[1] if add_if[0].call(sym)
    end
    return nil
  end

  def add(sym, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "#{self.class.name} for #{sym.inspect} has no valid handler (#{handler.inspect} was given)"
    end
    @hash[sym] = handler || handlerBlock if sym
  end

  def addIf(sym, conditionProc, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "addIf call for #{sym} in #{self.class.name} has no valid handler (#{handler.inspect} was given)"
    end
    @add_ifs[sym] = [conditionProc, handler || handlerBlock]
  end

  def copy(src, *dests)
    handler = self[src]
    return if !handler
    dests.each { |dest| add(dest, handler) }
  end

  def remove(key)
    @hash.delete(key)
  end

  def clear
    @hash.clear
    @add_ifs.clear
  end

  def trigger(sym, *args)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    handler = self[sym]
    return handler&.call(sym, *args)
  end
end

def self.triggerOnStatLoss(item, user, move_user, battle)
  return trigger(OnStatLoss, item, user, move_user, battle)
end
